<?php
declare(strict_types=1);require_once __DIR__.'/includes/public-site.php';$context=public_site_fallback_context();try{$context=public_site_context(app_pdo());}catch(Throwable $e){error_log('Public contact load failed: '.$e->getMessage());}$settings=$context['settings'];$address=public_site_format_address($settings);$socials=public_site_social_links($settings);?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Contact | <?=app_escape((string)$settings['restaurant_name'])?></title><link rel="stylesheet" href="assets/css/site.css?v=20260914"></head><body><?php public_site_render_header($settings,'contact');?><main class="page-main"><section class="page-hero"><div class="shell"><div class="eyebrow">Contact</div><h1>Talk to Stonefellows.</h1><p>Restaurant contact details are maintained from the Public Site settings in admin.</p></div></section><section class="section"><div class="shell contact-grid"><article class="content-card"><div class="eyebrow">Restaurant</div><h2>Get in touch.</h2><ul class="detail-list"><?php if($settings['phone']!==''):?><li><strong>Phone</strong><br><a class="contact-link" href="tel:<?=app_escape(preg_replace('/[^+0-9]/','',(string)$settings['phone'])??'')?>"><?=app_escape((string)$settings['phone'])?></a></li><?php endif;?><?php if($settings['email']!==''):?><li><strong>Email</strong><br><a class="contact-link" href="mailto:<?=app_escape((string)$settings['email'])?>"><?=app_escape((string)$settings['email'])?></a></li><?php endif;?><?php if($address!==''):?><li><strong>Address</strong><br><?=app_escape($address)?></li><?php endif;?><?php if($settings['hours_text']!==''):?><li><strong>Hours</strong><br><?=nl2br(app_escape((string)$settings['hours_text']))?></li><?php endif;?></ul></article><article class="content-card"><div class="eyebrow">Social</div><h2>Follow along.</h2><?php if($socials):?><ul class="detail-list"><?php foreach($socials as $label=>$url):?><li><a class="contact-link" target="_blank" rel="noopener noreferrer" href="<?=app_escape($url)?>"><?=app_escape($label)?> →</a></li><?php endforeach;?></ul><?php else:?><p>Social links have not been published yet.</p><?php endif;?></article></div></section></main><?php public_site_render_footer($settings);?><script src="assets/js/site.js?v=20260914"></script></body></html>
